// Pixel load event listener
jQuery(document).on("pmw:load-pixels", () => {

	if (wpmDataLayer?.pixels?.twitter?.pixel_id && !wpmDataLayer?.pixels?.twitter?.loaded) {
		if (wpm.consent.canPixelBeFired("marketing", "Twitter")) wpm.loadTwitterPixel()
	}
})

// add-to-cart event
jQuery(document).on("pmw:browser:add-to-cart", (event, payload) => {

	try {
		if(wpm.canNotFireTwitterEvent()) return

		const twitterData = payload.pixels?.twitter;
		if (!twitterData) return;

		if (twitterData.event_type === 'event') {
			twq("event", twitterData.event_id, twitterData.event_data)
			pmw.console.log("Twitter Pixel: add_to_cart event sent", twitterData.event_data)
		} else {
			// Legacy event
			twq("track", twitterData.event_name)
			pmw.console.log("Twitter Pixel: add_to_cart event sent")
		}
	} catch (e) {
		console.error(e)
	}
})

