/**
 * Twitter Ads Adapter
 * 
 * Adapts event data into Twitter Pixel format.
 * 
 * Documentation:
 * - https://business.twitter.com/en/help/campaign-measurement-and-analytics/conversion-tracking-for-websites.html
 * 
 * @since 1.51.0
 */

(function (wpm, $, undefined) {

	class TwitterAdapter {
		
		/**
		 * Adapt event data to Twitter Pixel format
		 * 
		 * @param {object} eventData - Event-specific data (product, order, etc.)
		 * @param {string} eventName - Standardized event name
		 * @param {object} context - Event context (user, page, etc.)
		 * @returns {object|null} Adapted data for Twitter or null if pixel not loaded
		 */
		adapt(eventData, eventName, context) {
			
			// Check if Twitter pixel is loaded
			if (!wpmDataLayer?.pixels?.twitter?.loaded) {
				return null;
			}
			
			const eventMap = {
				'add_to_cart': () => this.adaptAddToCart(eventData),
				'view_item': () => this.adaptViewContent(eventData),
				'add_to_wishlist': () => this.adaptAddToWishlist(eventData),
				'begin_checkout': () => this.adaptInitiateCheckout(eventData),
				'add_payment_info': () => this.adaptAddPaymentInfo(eventData),
				'search': () => this.adaptSearch(eventData),
				'purchase': () => this.adaptPurchase(eventData),
			};
			
			if (!eventMap[eventName]) {
				return null;
			}
			
			return eventMap[eventName]();
		}
		
		/**
		 * Build product content data
		 */
		buildProductContent(product) {
			return {
				content_type: 'product',
				content_id: wpmDataLayer.products[product.id].dyn_r_ids[wpmDataLayer.pixels.twitter.dynamic_remarketing.id_type],
				content_name: product.name,
				content_price: product.price,
				num_items: product.quantity,
			};
		}
		
		/**
		 * Adapt add_to_cart event
		 */
		adaptAddToCart(eventData) {
			if (!eventData?.product) return null;
			
			const product = eventData.product;
			const eventId = wpmDataLayer?.pixels?.twitter?.event_ids?.add_to_cart;
			
			if (eventId) {
				return {
					event_type: 'event',
					event_id: eventId,
					event_data: {
						value: product.quantity * product.price,
						currency: wpmDataLayer.shop.currency,
						contents: [this.buildProductContent(product)],
					}
				};
			} else {
				// Legacy event
				return {
					event_type: 'track',
					event_name: 'AddToCart',
					event_data: null
				};
			}
		}
		
		/**
		 * Adapt view_item event
		 */
		adaptViewContent(eventData) {
			const eventId = wpmDataLayer?.pixels?.twitter?.event_ids?.view_content;
			let eventDataObj = {};
			
			if (eventData?.product) {
				const product = eventData.product;
				eventDataObj = {
					value: product.quantity * product.price,
					currency: wpmDataLayer.shop.currency,
					contents: [this.buildProductContent(product)],
				};
			}
			
			if (eventId) {
				return {
					event_type: 'event',
					event_id: eventId,
					event_data: eventDataObj
				};
			} else {
				// Legacy event
				return {
					event_type: 'track',
					event_name: 'ViewContent',
					event_data: null
				};
			}
		}
		
		/**
		 * Adapt add_to_wishlist event
		 */
		adaptAddToWishlist(eventData) {
			if (!eventData?.product) return null;
			
			const product = eventData.product;
			const eventId = wpmDataLayer?.pixels?.twitter?.event_ids?.add_to_wishlist;
			let eventDataObj = {};
			
			if (product) {
				eventDataObj = {
					value: product.quantity * product.price,
					currency: wpmDataLayer.shop.currency,
					contents: [this.buildProductContent(product)],
				};
			}
			
			if (eventId) {
				return {
					event_type: 'event',
					event_id: eventId,
					event_data: eventDataObj
				};
			} else {
				// Legacy event
				return {
					event_type: 'track',
					event_name: 'AddToWishlist',
					event_data: null
				};
			}
		}
		
		/**
		 * Adapt begin_checkout event
		 */
		adaptInitiateCheckout(eventData) {
			const eventId = wpmDataLayer?.pixels?.twitter?.event_ids?.initiate_checkout;
			
			if (eventId) {
				return {
					event_type: 'event',
					event_id: eventId,
					event_data: {}
				};
			} else {
				// Legacy event
				return {
					event_type: 'track',
					event_name: 'InitiateCheckout',
					event_data: null
				};
			}
		}
		
		/**
		 * Adapt add_payment_info event
		 */
		adaptAddPaymentInfo(eventData) {
			const eventId = wpmDataLayer?.pixels?.twitter?.event_ids?.add_payment_info;
			
			if (eventId) {
				return {
					event_type: 'event',
					event_id: eventId,
					event_data: {}
				};
			} else {
				// Legacy event
				return {
					event_type: 'track',
					event_name: 'AddPaymentInfo',
					event_data: null
				};
			}
		}
		
		/**
		 * Adapt search event
		 */
		adaptSearch(eventData) {
			const eventId = wpmDataLayer?.pixels?.twitter?.event_ids?.search;
			
			if (eventId) {
				return {
					event_type: 'event',
					event_id: eventId,
					event_data: {
						search_string: wpm.getSearchTermFromUrl(),
					}
				};
			} else {
				// Legacy event
				return {
					event_type: 'track',
					event_name: 'Search',
					event_data: null
				};
			}
		}
		
		/**
		 * Adapt purchase event
		 */
		adaptPurchase(eventData) {
			const eventId = wpmDataLayer?.pixels?.twitter?.event_ids?.purchase;
			
			if (eventId) {
				return {
					event_type: 'event',
					event_id: eventId,
					event_data: {
						value: wpmDataLayer.order.value.marketing,
						currency: wpmDataLayer.order.currency,
						conversion_id: wpmDataLayer.order.id,
						contents: wpm.twitterGetOrderContentIdsV2(),
					}
				};
			} else {
				// Legacy event
				return {
					event_type: 'track',
					event_name: 'Purchase',
					event_data: {
						order_id: wpmDataLayer.order.id,
						value: wpmDataLayer.order.value.marketing,
						currency: wpmDataLayer.order.currency,
						num_items: wpmDataLayer.order.quantity,
						content_ids: wpm.twitterGetOrderContentIdsV1(),
					}
				};
			}
		}
	}
	
	// Register the adapter
	wpm.registerAdapter('twitter', new TwitterAdapter(), {
		supportsS2S: false,
		supportsEventDeduplication: false,
		isActive: () => wpmDataLayer?.pixels?.twitter?.pixel_id ? true : false
	});
	
}(window.wpm = window.wpm || {}, jQuery));
